import{_ as i,o as n,c as s,a3 as e}from"./chunks/framework.BvvarXmc.js";const m=JSON.parse('{"title":"‍ Dashboard Perwalian Wali Kelas","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-guru/dashboard-walikelas.md","filePath":"panduan-guru/dashboard-walikelas.md","lastUpdated":null}'),t={name:"panduan-guru/dashboard-walikelas.md"};function l(r,a,d,o,u,k){return n(),s("div",null,[...a[0]||(a[0]=[e('<h1 id="‍-dashboard-perwalian-wali-kelas" tabindex="-1">‍ Dashboard Perwalian Wali Kelas <a class="header-anchor" href="#‍-dashboard-perwalian-wali-kelas" aria-label="Permalink to &quot;‍ Dashboard Perwalian Wali Kelas&quot;">​</a></h1><p>Guru yang ditugaskan sebagai Wali Kelas memiliki akses ke pusat monitoring terpadu untuk memantau kondisi siswa di kelas binaannya secara komprehensif.</p><hr><h2 id="_1-widget-utama-dashboard-wali-kelas" tabindex="-1">1. Widget Utama Dashboard Wali Kelas <a class="header-anchor" href="#_1-widget-utama-dashboard-wali-kelas" aria-label="Permalink to &quot;1. Widget Utama Dashboard Wali Kelas&quot;">​</a></h2><p>Saat membuka menu <strong>Dashboard Wali Kelas</strong>, Anda akan melihat ringkasan:</p><ul><li><strong>Jumlah Siswa Aktif</strong>: Total siswa laki-laki dan perempuan di kelas binaan.</li><li><strong>Grafik Kehadiran Hari Ini</strong>: Berapa siswa yang hadir, izin, sakit, atau tanpa keterangan.</li><li><strong>Peringatan Kehadiran Rendah</strong>: Daftar siswa yang memiliki catatan alfa atau keterlambatan lebih dari batas toleransi sekolah.</li><li><strong>Status Pembayaran SPP Kelas</strong>: Persentase siswa yang sudah lunas dan yang masih memiliki tunggakan SPP bulan ini (tanpa membuka rincian rekening pribadi siswa).</li></ul><hr><h2 id="_2-catatan-khusus-pembinaan-karakter-siswa" tabindex="-1">2. Catatan Khusus &amp; Pembinaan Karakter Siswa <a class="header-anchor" href="#_2-catatan-khusus-pembinaan-karakter-siswa" aria-label="Permalink to &quot;2. Catatan Khusus &amp; Pembinaan Karakter Siswa&quot;">​</a></h2><ol><li>Pada daftar siswa kelas binaan, klik nama salah satu siswa.</li><li>Buka tab <strong>Catatan Perilaku / Konseling</strong>.</li><li>Klik tombol <strong>+ Tambah Catatan</strong>.</li><li>Masukkan poin catatan: <ul><li>Kategori: Prestasi Positif, Sikap/Kedisiplinan, atau Konseling Masalah.</li><li>Keterangan kejadian dan tindak lanjut wali kelas.</li></ul></li><li>Catatan ini dapat diteruskan ke Guru BK (Bimbingan Konseling) atau dicantumkan pada lembar catatan wali kelas di buku rapor semester.</li></ol>',9)])])}const b=i(t,[["render",l]]);export{m as __pageData,b as default};
